  const valid=[],blocked=[];
  for(const id of ids){const value={...state.tx[id],pending:false,pendingReason:''},temp=structuredClone(state);temp.tx[id]=value;const issue=Ledger.project(temp).issues.find(i=>i.id===id);(issue?blocked:valid).push({id,value,issue});}
