function sourceUpdated(old,fresh){return old.raw?.classificationVersion!==fresh.raw?.classificationVersion||JSON.stringify(old.raw?.machine||{})!==JSON.stringify(fresh.raw?.machine||{})||old.raw?.status!==fresh.raw.status||old.raw?.payment!==fresh.raw.payment||old.raw?.paymentKey!==fresh.raw.paymentKey||old.amount!==fresh.amount||old.date!==fresh.date;}
const importMachineFields=['kind','date','amount','account','bucket','toAccount','toOwner','toBucket','purpose','transferDirection','receivedAmount','payerType','reviewStatus','pending','pendingReason','refund','refundDate','refundAccount','linkedTo','linkedRole','merchant'];
function inferredManualFields(old){if(Array.isArray(old.manualFields))return old.manualFields;const machine=old.raw?.machine||{};if(!old.userEditedAt)return [];return importMachineFields.filter(k=>Object.prototype.hasOwnProperty.call(machine,k)&&JSON.stringify(old[k])!==JSON.stringify(machine[k]));}
