  const flowText=t=>{const f=t.raw?.recognition?.flow||{};if(f.fromLabel&&f.toLabel)return `${f.fromLabel} → ${f.toLabel}`;if(f.toLabel)return `→ ${f.toLabel}`;if(f.fromLabel)return `${f.fromLabel} → ${t.merchant||'交易对方'}`;return '资金流向待确认';};
