    Ledger.validateEntity('tx',value);const temp=structuredClone(state);temp.tx[t.id]=value;const p=Ledger.project(temp),ownIssues=p.issues.filter(i=>i.id===t.id);
    if(!value.pending&&ownIssues.some(i=>!/退款时间未确认/.test(i.reason)))throw Error(ownIssues[0].reason+'；也可勾选待核对后暂存');
    if(!value.pending&&!payerType&&['expense','transfer','lend','repay'].includes(value.kind)){const before=Ledger.project(state).balances[value.account]?.[value.owner]?.[value.bucket]||0,after=p.balances[value.account]?.[value.owner]?.[value.bucket];if(after<0&&after<before)throw Error('所选资金不足。请核对余额基准，或勾选待核对暂存。');}
