function debtForm(id){assertEditable();const d=state.debt[id]||{id:Ledger.uuid(),owner:ownerMode(),name:'',side:'owed',opening:0,asOf:localNow().slice(0,10),counterparty:''};modal('欠款 / 应收',`<form id="debtForm"><div class="form-grid"><label>归属<select name="owner">${ownerOptions(d.owner)}</select></label><label>性质<select name="side">${opt('owed','我欠别人',d.side)+opt('claim','别人欠我',d.side)}</select></label><label>名称<input name="name" required maxlength="100" value="${E(d.name)}" placeholder="例如：花呗、借给朋友"></label><label>对方<input name="counterparty" maxlength="100" value="${E(d.counterparty)}"></label><label>初始未结金额（元）<input name="opening" type="number" min="0" step="0.01" required value="${(d.opening/100).toFixed(2)}"></label><label>起始日期<input type="date" name="asOf" required value="${d.asOf}"></label></div><div class="note">此处填写未结清的债权或欠款，不会增加或减少银行卡余额。之后在“记一笔”中选择借入、借出、还款或收回借款。</div><p class="form-error" id="debtError"></p><div class="modal-actions"><button class="btn primary">保存</button></div></form>`);$('debtForm').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));await save('debt',d.id,{...d,...v,opening:Number(v.opening)===0?0:toCents(v.opening)});closeModal();}catch(e){$('debtError').textContent=e.message;}};}
function taxonomyForm(type,id){assertEditable();const old=state[type][id],v=old||{id:Ledger.uuid(),name:'',color:mode==='b'?'#c0a6ee':'#96dfbb'};modal((old?'编辑':'添加')+(type==='category'?'分类':'标签'),`<form id="taxForm"><div class="form-grid"><label>名称<input name="name" required maxlength="40" value="${E(v.name)}"></label><label>颜色<input name="color" type="color" value="${v.color}"></label></div><div class="note">删除后无法新选用；历史账单上的名称仍保留，避免丢失原记录。</div><div id="taxError" class="form-error"></div><div class="modal-actions">${old?'<button class="btn danger" id="deleteTax" type="button">删除</button>':''}<button class="btn primary">保存</button></div></form>`);$('taxForm').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(active(state[type]).some(t=>t.id!==v.id&&t.name===d.name.trim()))throw Error('这个名称已存在');await save(type,v.id,{...v,name:d.name.trim(),color:d.color});closeModal();}catch(e){$('taxError').textContent=e.message;}};if(old)$('deleteTax').onclick=async()=>{await save(type,id,{...old,deleted:true});closeModal();};}
function showHistory(type,id){const history=data.ops.filter(o=>o.type===type&&o.entity===id).sort((a,b)=>b.at.localeCompare(a.at));modal('修改历史',history.map(o=>`<div class="history-item"><strong>${E(name(o.actor))} · ${E(new Date(o.at).toLocaleString('zh-CN'))}</strong><p>${o.value.deleted?'移入回收站':o.parents.length?'更新记录':'创建记录'}</p><details><summary class="subtle">展开此版本</summary><pre class="raw">${E(JSON.stringify(o.value,null,2))}</pre></details></div>`).join(''));}
