function pairForm(index){assertEditable();const pairs=Ledger.candidates(state).filter(x=>mode==='shared'||x.out.owner===ownerMode()||x.inc.owner===ownerMode()||x.out.toOwner===ownerMode()||x.inc.toOwner===ownerMode()),pair=pairs[index];if(!pair)return;const {out,inc,fee}=pair;modal('合并为一笔转账',`<form id="pairForm"><div class="note">${E(aname(out.account))} 转出 ¥${money(out.amount)} → ${E(aname(inc.account))} 到账 ¥${money(inc.amount)}${fee?`<br>差额 ¥${money(fee)} 记作手续费支出。`:''}<br>两端原始订单都会保留，转入明细不重复计算。</div><div class="form-grid"><label>资金原本属于谁<select name="owner">${ownerOptions(out.owner)}</select></label><label>资金用途<select name="purpose">${Object.entries(purposeNames).map(([k,n])=>opt(k,n,out.owner===inc.owner?'internal':'custody')).join('')}</select></label><label>转出部分<select name="bucket">${opt('liquid','流动资金','liquid')+opt('savings','存款','liquid')}</select></label><label>转入部分<select name="toBucket">${opt('liquid','流动资金','liquid')+opt('savings','存款','liquid')}</select></label><label class="full">赠与 / 借还款的接收所有人<select name="toOwner">${ownerOptions(inc.owner)}</select></label><label class="full check-row"><input type="checkbox" name="remember">记住此内部转账规则（只适用于所有权不变）</label></div><p id="pairError" class="form-error"></p><div class="modal-actions"><button class="btn primary">确认合并</button></div></form>`);$('pairForm').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));await mergePair(out,inc,v,!!v.remember);closeModal();toast('已合并转账，原始记录仍保留');}catch(e){$('pairError').textContent=e.message;}};}
async function mergePair(out,inc,options,remember=false){const owner=options.owner,toOwner=['gift','loan','loan-repay'].includes(options.purpose)?options.toOwner:owner;const main={...out,...options,owner,toOwner,kind:'transfer',transferDirection:'internal',toAccount:inc.account,transferInDate:inc.date,amount:out.amount,receivedAmount:inc.amount,fee:Math.max(0,out.amount-inc.amount),pending:false,pendingReason:'',pairedId:inc.id,merchant:out.merchant||purposeNames[options.purpose]},leg={...inc,linkedTo:out.id,linkedRole:'transfer-leg',pending:false};const changes=[{type:'tx',id:out.id,value:main},{type:'tx',id:inc.id,value:leg}];if(remember){if(owner!==toOwner)throw Error('赠与和借还款需要逐次确认，不保存自动规则');changes.push({type:'rule',id:Ledger.uuid(),value:{ruleType:'transfer',owner,from:out.account,to:inc.account,outMerchant:out.merchant,inMerchant:inc.merchant,outKind:out.raw?.kind||'',inKind:inc.raw?.kind||'',outSource:out.raw?.source||'',inSource:inc.raw?.source||'',purpose:options.purpose,bucket:options.bucket,toBucket:options.toBucket}});}await saveBatch(changes);}
async function applyAutoRules(){const rules=active(state.rule).filter(r=>r.ruleType==='transfer');let count=0;for(const rule of rules){const pairs=Ledger.candidates(state).filter(p=>p.minutes<=10&&p.out.account===rule.from&&p.inc.account===rule.to&&p.out.owner===rule.owner&&p.out.merchant===rule.outMerchant&&p.inc.merchant===rule.inMerchant&&(p.out.raw?.kind||'')===rule.outKind&&(p.inc.raw?.kind||'')===rule.inKind&&(p.out.raw?.source||'')===(rule.outSource||'')&&(p.inc.raw?.source||'')===(rule.inSource||''));for(const p of pairs){if(pairs.filter(q=>q.out.id===p.out.id||q.inc.id===p.inc.id).length!==1)continue;if(state.tx[p.out.id]?.kind==='transfer'||state.tx[p.inc.id]?.linkedTo)continue;await mergePair(p.out,p.inc,{owner:rule.owner,toOwner:rule.owner,purpose:rule.purpose,bucket:rule.bucket,toBucket:rule.toBucket});count++;}}return count;}
function refundForm(id){
  assertEditable();const r=state.tx[id],parents=active(state.tx).filter(t=>t.id!==r.id&&t.owner===r.owner&&!t.pending&&['expense','transfer','neutral'].includes(t.kind)&&['expense','transfer'].includes(t.raw?.recognition?.baseEventType||t.raw?.recognition?.eventType||t.kind)).sort((a,b)=>{const match=t=>importedRelationKeys(r).some(k=>importedRelationKeys(t).includes(k))?0:relationText(t.merchant)===relationText(r.merchant)?1:2;return match(a)-match(b)||b.date.localeCompare(a.date);});
  modal('关联原交易',`<form id="refundForm"><div class="note">退款 ${E(r.merchant)} · ¥${money(r.amount)}<br>退款到账已经按原始渠道记录。关联用于计算原订单实付金额，也可关联被退回的微信转账。</div><label class="field">对应的原交易<select name="expense" required>${opt('','请选择原交易','')+parents.map(t=>opt(t.id,`${t.date.slice(0,10)} · ${t.merchant} · ¥${money(t.amount)} · ${t.raw?.orderId||''}`,'')).join('')}</select></label><label class="field" style="margin-top:16px">退款实际入账账户（外部代付可留空）<select name="account">${accountOptions(r.account)}</select></label><p id="refundError" class="form-error"></p><div class="modal-actions"><button class="btn primary">确认关联</button></div></form>`);
  $('refundForm').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target)),t=state.tx[v.expense];if(!t)throw Error('请选择原交易');const external=['family-card','huabei-repayment-history'].includes(t.payerType)||(!t.account&&t.payerType==='huabei-history');if(!external&&!v.account)throw Error('请选择退款实际入账账户');const total=active(state.tx).filter(x=>x.kind==='refund'&&x.linkedTo===t.id&&x.id!==r.id&&!x.pending).reduce((s,x)=>s+x.amount,0);if(total+r.amount>t.amount)throw Error('退款合计超过原交易金额，请检查是否重复退款');const changes=[],base=t.raw?.recognition?.baseEventType;if(t.kind==='neutral'&&t.raw?.recognition?.orderStatus==='closed'&&['expense','transfer'].includes(base))changes.push({type:'tx',id:t.id,value:{...t,kind:base,raw:{...t.raw,machine:{...(t.raw.machine||{}),kind:base,settlement:'paid-then-refunded'}}}});changes.push({type:'tx',id:r.id,value:{...r,account:external?'':v.account,owner:t.owner,bucket:t.bucket,payerType:external?t.payerType:r.payerType,linkedTo:t.id,reviewStatus:'',pending:false,manualFields:[...new Set([...(r.manualFields||[]),'account','linkedTo'])],userEditedAt:new Date().toISOString()}});await saveBatch(changes);closeModal();toast('退款已关联，不会计作普通收入');}catch(e){$('refundError').textContent=e.message;}};
}
async function purgeTransactions(ids){assertEditable();const unique=[...new Set(ids)].filter(id=>state.tx[id]?.deleted);if(!unique.length)return;const ops=unique.map(id=>Ledger.operation([], 'purge', id, {targetType:'tx',targetId:id}, actor, device, []));data=await Store.append(ops);refreshState();render();scheduleSync();}
function showTrash(){const list=Object.values(state.tx).filter(t=>t.deleted);modal('回收站',list.length?`<div class="note">恢复会保留原记录；彻底移除会写入删除标记并同步到双方设备，之后可重新导入建立新记录。它会清除当前有效账本内容；GitHub 历史提交中的加密快照不会自动改写。</div>${list.map(t=>`<div class="list-row"><div>${E(t.merchant||kindNames[t.kind])}<p>${E(t.date)} · ¥${money(t.amount)}</p></div><button class="btn small" data-restore-tx="${E(t.id)}">恢复</button><button class="btn small danger" data-purge-tx="${E(t.id)}">彻底移除</button></div>`).join('')}<div class="modal-actions"><button class="btn danger" data-clear-trash>清空回收站</button></div>`:empty('回收站是空的','删除的账单会保留修改历史；重新导入时可选择重新识别。'));}
function download(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function backup(){assertEditable();download('星账双人备份_'+localNow().slice(0,10)+'.json',JSON.stringify({app:'star-ledger-duo',schema:2,exportedAt:new Date().toISOString(),ops:data.ops},null,2));toast('备份已开始下载，包含所有人账单，请妥善保管');}
async function restore(file){assertEditable();if(!file)return;if(file.size>50*1024*1024)throw Error('备份超过 50 MB，请拆分归档');const v=JSON.parse(await file.text());if(v.app==='star-ledger'&&v.version===1){if(!Array.isArray(v.records))throw Error('旧版备份格式无效');const records=v.records.map(validateRecord);modal('迁移旧版账本',`<form id="migrateForm"><div class="note">读取到 ${records.length} 笔旧版记录。旧版没有账户信息，迁移后先标为待核对，不影响余额。原文件不会改变。</div><label class="field">这些记录属于谁<select name="owner">${ownerOptions(ownerMode())}</select></label><div class="modal-actions"><button class="btn primary">确认迁移</button></div></form>`);$('migrateForm').onsubmit=async e=>{e.preventDefault();const owner=new FormData(e.target).get('owner');const changes=records.filter(r=>!state.tx['v1:'+owner+':'+r.id]).map(r=>({type:'tx',id:'v1:'+owner+':'+r.id,value:{owner,kind:r.type,date:r.date,amount:r.amount,merchant:r.merchant,note:r.note,account:'',bucket:'liquid',category:active(state.category).find(c=>c.name===r.category)?.id||'',tags:[],refund:0,pending:true,pendingReason:'旧版数据缺少资金账户，请补全',raw:{source:r.source,orderId:r.orderId,status:r.status},importKeys:['import:'+`${owner}|${r.source}|order:${r.orderId}|${r.type}`]}}));await saveBatch(changes);closeModal();navigate('review');toast('旧版记录已迁移，原始备份保留');};return;}if(v.app!=='star-ledger-duo'||v.schema!==2)throw Error('这不是星账双人版备份');const merged=Ledger.merge(data.ops,v.ops);for(const op of merged)Ledger.validateEntity(op.type,op.value);confirm('合并恢复备份',`将合并 ${merged.length-data.ops.length} 条新版本记录，已有记录不会被整本覆盖。发生同时修改时需在核对页确认。`,async()=>{data=await Store.append(v.ops);refreshState();render();scheduleSync();toast('备份已合并');});}
function exportCSV(){const rows=ledgerRows();const cell=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';const lines=[['日期','所有人','类型','原金额','净消费金额','交易对方','账户','资金性质','用途','分类','标签','备注','订单号','待核对'],...rows.map(t=>[t.date,name(t.owner),kindNames[t.kind],(t.amount/100).toFixed(2),t.kind==='expense'?(Ledger.netExpense(t,state)/100).toFixed(2):'',t.merchant,aname(t.account),bucketName(t.bucket),purposeNames[t.purpose]||'',state.category[t.category]?.name||'',t.tags.map(id=>state.tag[id]?.name).join(' / '),t.note,t.raw?.orderId||'',t.pending?'是':'否'])];download('星账明细_'+localNow().slice(0,10)+'.csv','\uFEFF'+lines.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function sampleData(){let ops=initOps();const add=(type,id,v)=>{ops.push(Ledger.operation(ops,type,id,v,'a','demo'));};const first=monthNow()+'-01';const account=(name,holder,opening,type='银行卡')=>({name,holder,opening,asOf:first,type});add('profile','a',{name:'青禾'});add('profile','b',{name:'星野'});add('account','demo-bank',account('招商银行 · 1208','a',{a:{liquid:200000,savings:500000},b:{liquid:0,savings:100000}}));add('account','demo-wechat',account('微信余额','a',{a:{liquid:85000,savings:0},b:{liquid:0,savings:0}},'微信余额'));add('account','demo-bank-b',account('建设银行 · 0621','b',{a:{liquid:0,savings:80000},b:{liquid:260000,savings:620000}}));
const tx=(id,day,kind,amount,merchant,category,owner='a',account='demo-wechat',more={})=>add('tx',id,{owner,kind,date:monthNow()+'-'+String(Math.min(day,new Date().getDate())).padStart(2,'0')+' 12:30:00',amount,merchant,category:'cat-'+category,account,bucket:'liquid',tags:['tag-0'],note:'示例记录',pending:false,refund:0,...more});tx('demo1',2,'expense',2850,'瑞幸咖啡',0);tx('demo2',4,'expense',6800,'周末晚餐',0);tx('demo3',6,'expense',600,'上海地铁',2);tx('demo4',8,'expense',12900,'换季衣物',1,'a','demo-bank',{refund:3900,refundDate:monthNow()+'-09 10:00:00'});tx('demo5',10,'income',180000,'实习津贴',9,'a','demo-bank');tx('demo6',11,'transfer',50000,'本月存起来',11,'a','demo-bank',{toAccount:'demo-bank',toOwner:'a',toBucket:'savings',purpose:'deposit'});tx('demo7',12,'expense',4690,'超市采购',3);tx('demo8',14,'expense',8900,'上海书城',5);tx('demo9',16,'expense',4200,'周末电影',4);tx('demo10',7,'expense',8800,'两人的午餐',0,'b','demo-bank-b');tx('demo11',13,'transfer',30000,'存一笔小小的期待',11,'b','demo-bank-b',{toAccount:'demo-bank-b',toOwner:'b',toBucket:'savings',purpose:'deposit'});add('debt','demo-debt',{owner:'a',name:'待还分期',side:'owed',opening:65000,asOf:first,counterparty:'示例'});return {schema:2,ops};}
const actions={
'new-account':()=>accountForm(), 'new-debt':()=>debtForm(), 'sync':()=>doSync(),
'prev-month':()=>changeMonth(-1),'next-month':()=>changeMonth(1),'prev-savings-month':()=>changeSavingsMonth(-1),'next-savings-month':()=>changeSavingsMonth(1),'all-month':()=>{const w=periodWindow();filter=blankFilter();filter.start=w.start.slice(0,10);filter.end=w.end.slice(0,10);view='ledger';page=1;render();},
'prev-page':()=>{page--;renderLedger();},'next-page':()=>{page++;renderLedger();},'reset-filter':()=>{filter=blankFilter();page=1;renderLedger();},
'bulk-confirm-pending':()=>bulkPending('confirm'),'bulk-delete-pending':()=>bulkPending('delete'),'bulk-confirm-ledger':()=>bulkLedger('confirm'),'bulk-pending-ledger':()=>bulkLedger('pending'),'bulk-delete-ledger':()=>bulkLedger('delete'),
'export-csv':exportCSV,'commit-import':commitImport,'backup':backup,'restore':()=>{$('backupInput').click();},'trash':showTrash,
'exit-demo':async()=>{demo=false;data=await Store.get('ledger')||realData;refreshState();render();},
'lock-sync':async()=>{await Store.lock();render();toast('同步连接已锁定，本地账本仍可使用');},
'disconnect':()=>confirm('断开此设备的同步连接？','仅移除此设备保存的授权和同步状态，本地账本和远端数据保留。',async()=>{await Store.disconnect();connectionInfo=null;syncInfo=null;render();}),
'storage-persist':async()=>{const yes=await navigator.storage?.persist?.();toast(yes?'浏览器已同意保留本地数据，仍请定期备份':'浏览器未授予持久存储，已保存记录未受影响，请定期备份');}
};
function changeSavingsMonth(delta){const [y,m]=month.split('-').map(Number),d=new Date(y,m-1+delta,1);month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;periodAnchor=month+'-01';render();}
function changeMonth(delta){
  const d=fromDate(periodAnchor);
  if(periodMode==='week')d.setDate(d.getDate()+delta*7);
  else if(periodMode==='year')d.setFullYear(d.getFullYear()+delta);
  else d.setMonth(d.getMonth()+delta);
  periodAnchor=localDate(d);month=periodAnchor.slice(0,7);render();
}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav);return;}if(b.dataset.mode){switchMode(b.dataset.mode);return;}if(b.dataset.act){e.preventDefault();const fn=actions[b.dataset.act];if(fn)await fn();return;}if(b.dataset.editTx){if(!state.tx[b.dataset.editTx]){toast('导入预览尚未保存，确认导入后可编辑');return;}editSequence=view==='ledger'?ledgerRows().map(x=>x.id):view==='review'?active(state.tx).filter(x=>x.pending).sort((a,b)=>b.date.localeCompare(a.date)).map(x=>x.id):[];txForm(b.dataset.editTx);return;}if(b.dataset.account){accountForm(b.dataset.account);return;}if(b.dataset.debt){debtForm(b.dataset.debt);return;}if(b.dataset.category!==undefined){const w=periodWindow();filter=blankFilter();filter.category=b.dataset.category;filter.start=w.start.slice(0,10);filter.end=w.end.slice(0,10);page=1;navigate('ledger');return;}if(b.dataset.taxonomy){taxonomyForm(b.dataset.taxonomy);return;}if(b.dataset.editTax){const [type,id]=b.dataset.editTax.split(':');taxonomyForm(type,id);return;}if(b.dataset.pair!==undefined){pairForm(+b.dataset.pair);return;}if(b.dataset.refund){refundForm(b.dataset.refund);return;}if(b.dataset.conflict){conflictForm(b.dataset.conflict);return;}if(b.dataset.restoreTx){const t=state.tx[b.dataset.restoreTx];await save('tx',t.id,{...t,deleted:false});showTrash();return;}if(b.dataset.purgeTx){confirm('彻底移除这笔记录？','它会从当前账本和同步后的有效数据中移除，之后只能通过重新导入建立新记录。',async()=>{await purgeTransactions([b.dataset.purgeTx]);showTrash();});return;}if(b.dataset.clearTrash){const ids=Object.values(state.tx).filter(t=>t.deleted).map(t=>t.id);confirm('清空回收站？','这些记录会被双方设备永久移除，之后重新导入会按新记录重新识别。',async()=>{await purgeTransactions(ids);showTrash();});return;}if(b.dataset.deleteRule){const r=state.rule[b.dataset.deleteRule];await save('rule',r.id,{...r,deleted:true});return;}if(b.dataset.unlink){const t=state.tx[b.dataset.unlink],parent=state.tx[t.linkedTo];const changes=[{type:'tx',id:t.id,value:{...t,linkedTo:'',linkedRole:'',pending:true,pendingReason:'已解除转账关联，请重新核对'}}];if(parent)changes.push({type:'tx',id:parent.id,value:{...parent,pending:true,pendingReason:'已解除转账关联，请核对两端记录',pairedId:''}});await saveBatch(changes);closeModal();return;}}catch(err){toast(err.message);}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-day]');if(t){filter=blankFilter();filter.day=t.dataset.day;filter.kind='expense';navigate('ledger');}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.day){e.preventDefault();filter=blankFilter();filter.day=e.target.dataset.day;filter.kind='expense';navigate('ledger');}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){filter.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;page=1;renderLedger();$('search')?.focus();try{$('search').setSelectionRange(pos,pos);}catch{}},250);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-select-all-pending]'))document.querySelectorAll('[data-select-pending]').forEach(x=>{x.checked=e.target.checked;});if(e.target.matches('[data-select-all-ledger]'))document.querySelectorAll('[data-select-ledger]').forEach(x=>{x.checked=e.target.checked;});const id=e.target.id;if(id==='periodAnchor'){periodAnchor=e.target.value||localNow().slice(0,10);month=periodAnchor.slice(0,7);render();}if(id==='periodMode'){periodMode=e.target.value||'month';render();}if(id==='savingsMonth'){month=e.target.value||monthNow();periodAnchor=month+'-01';render();}const fields={kindFilter:'kind',categoryFilter:'category',tagFilter:'tag',ledgerStart:'start',ledgerEnd:'end'};if(fields[id]){filter[fields[id]]=e.target.value;filter.day='';filter.month='';page=1;renderLedger();}if(id==='billFile')parseBill(e.target.files[0]).catch(e=>toast(e.message));if(id==='backupInput'){restore(e.target.files[0]).catch(e=>toast('恢复失败：'+e.message));e.target.value='';}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();parseBill(e.dataTransfer.files[0]).catch(e=>toast(e.message));}});
document.addEventListener('submit',async e=>{if(!['profileForm','connectionForm','unlockForm'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]')||f.querySelector('button'),d=Object.fromEntries(new FormData(f));if(b)b.disabled=true;try{assertEditable();if(f.id==='profileForm'){await saveBatch([{type:'profile',id:'a',value:{name:d.a.trim()}},{type:'profile',id:'b',value:{name:d.b.trim()}}]);actor=d.actor;await Store.set('actor',actor);render();toast('昵称与记录人已保存');}if(f.id==='connectionForm'){await Store.connect({owner:d.owner.trim(),repo:d.repo.trim(),branch:d.branch.trim()},d.token,d.password,!!d.remember);connectionInfo=await Store.get('connection');f.reset();await doSync();render();}if(f.id==='unlockForm'){await Store.unlock(d.password);f.reset();await doSync();render();}}catch(err){toast(err.message);}finally{if(b)b.disabled=false;}});
$('addEntry').onclick=()=>{try{txForm();}catch(e){toast(e.message);}};$('quickTransfer').onclick=()=>{try{txForm(null,{kind:'transfer',purpose:mode==='shared'?'deposit':'internal',toBucket:mode==='shared'?'savings':'liquid'});}catch(e){toast(e.message);}};$('modalClose').onclick=closeModal;$('confirmCancel').onclick=()=>$('confirmModal').close();$('syncBtn').onclick=()=>doSync();$('demoBtn').onclick=()=>{if(!ready){toast('请先允许浏览器本地存储');return;}realData=data;demo=true;data=sampleData();mode='a';periodAnchor=localNow().slice(0,10);month=monthNow();view='overview';render();};
window.addEventListener('online',()=>scheduleSync());document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&!demo&&ready){data=await Store.get('ledger')||data;refreshState();render();scheduleSync();}});
if(typeof BroadcastChannel!=='undefined'){const channel=new BroadcastChannel('star-ledger-duo');channel.onmessage=async()=>{if(!demo&&ready){data=await Store.get('ledger')||data;refreshState();render();}};const originalSave=saveBatch;saveBatch=async(...args)=>{const result=await originalSave(...args);channel.postMessage('changed');return result;};}
if(document.modelContext?.registerTool){const ctl=new AbortController();window.addEventListener('pagehide',()=>ctl.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'switch_ledger_mode',title:'切换星账模式',description:'切换到绿色方、紫色方或双方存款视图，不修改账单。',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['a','b','shared']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['a','b','shared'].includes(input.mode)||Object.keys(input).some(k=>k!=='mode'))throw Error('无效模式');switchMode(input.mode);return {mode,view};}},{signal:ctl.signal})).catch(()=>{});}catch{}}
async function start(){try{await Store.open();device=await Store.get('device');if(!device){device=Ledger.uuid();await Store.set('device',device);}actor=await Store.get('actor')||'a';mode=await Store.get('mode')||'a';data=await Store.append(initOps());connectionInfo=await Store.get('connection');syncInfo=await Store.get('syncState');ready=true;}catch(e){toast(e.message);}render();if(location.protocol==='https:'||location.hostname==='localhost'){try{const reg=await navigator.serviceWorker?.register('./sw.js');if(reg){await navigator.serviceWorker.ready;offlineStatus='离线资源已准备好；未同步数据仍只在本机';if($('offlineState'))$('offlineState').textContent=offlineStatus;}}catch{offlineStatus='离线缓存未成功，请保持联网并重试';if($('offlineState'))$('offlineState').textContent=offlineStatus;}}}
start();

async function commitImport(){if(ioBusy)throw Error("正在处理文件，请稍候");ioBusy=true;try{return await importNow();}finally{ioBusy=false;}}
